}

{
  "command": "git diff --cached --quiet; rc=$?; if [ $rc -eq 0 ]; then echo 'No staged changes'; else echo 'Staged changes exist'; fi; exit $rc"
}

{
  "command": "for f in 'data/camera roll/58c1eae1-89dd-48d2-9a66-8efa4cae8843.JPEG' 'data/camera roll/IMG-20200809-WA0047.jpg' 'data/camera roll/IMG_1676.JPEG'; do sips -g pixelWidth -g pixelHeight \"$f\" 2>/dev/null | awk -v f=\"$f\" 'NR==1{next} /pixelWidth:/{w=$2} /pixelHeight:/{h=$2} END{print f \": \" w \"x\" h}'; done"
}

{
  "command": "for f in 'data/camera roll/58c1eae1-89dd-48d2-9a66-8efa4cae8843.JPEG' 'data/camera roll/IMG-20200809-WA0047.jpg' 'data/camera roll/IMG_1676.JPEG'; do sips -g format \"$f\" 2>/dev/null | awk -v f=\"$f\" 'NR==1{next} /format:/{print f \": \" $2}'; done"
